/bin/bash -lc "cat > /tmp/forma-browser-check/check.cjs <<'EOF'
const {chromium} = require('playwright');
const assert = require('node:assert/strict');
(async () => {
  const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
  const context = await browser.newContext({viewport: {width: 1280, height: 1000}});
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto('http://localhost:5173');
  await page.getByRole('heading', {name: 'Make yourself at home.'}).waitFor();
  assert.equal(await page.locator('html').getAttribute('lang'), 'en');
  await page.screenshot({path: '/tmp/forma-en.png', fullPage: true});
  await page.getByRole('combobox', {name: 'Interface language'}).click();
  await page.getByRole('textbox', {name: 'Filter', exact: true}).waitFor();
  await page.getByRole('option', {name: 'Русский', exact: true}).click();
  await page.getByRole('heading', {name: 'Чувствуйте себя как дома.'}).waitFor();
  assert.equal(await page.locator('html').getAttribute('lang'), 'ru');
  assert.equal(await page.evaluate(() => localStorage.getItem('interface-language')), 'ru');
  assert.equal(await page.title(), 'Настройки языка · Forma');
  assert.match(await page.locator('.format-examples').innerText(), /12\\s345,67/);
  await page.getByRole('combobox', {name: 'Язык интерфейса'}).click();
  await page.getByRole('textbox', {name: 'Фильтр', exact: true}).waitFor();
  await page.keyboard.press('Escape');
  await page.reload();
  await page.getByRole('heading', {name: 'Чувствуйте себя как дома.'}).waitFor();
  assert.equal(await page.locator('input[value=\"ru\"]').isChecked(), true);
  await page.locator('input[value=\"ru\"]').focus();
  await page.keyboard.press('ArrowLeft');
  await page.getByRole('heading', {name: 'Make yourself at home.'}).waitFor();
  await page.locator('.language-option').nth(1).click();
  await page.setViewportSize({width: 375, height: 812});
  await page.screenshot({path: '/tmp/forma-ru-mobile.png', fullPage: true});
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth), true);
  await context.close();

  const blocked = await browser.newContext();
  await blocked.addInitScript(() => {
    Storage.prototype.getItem = () => {throw new Error('Storage unavailable');};
    Storage.prototype.setItem = () => {throw new Error('Storage unavailable');};
  });
  const blockedPage = await blocked.newPage();
  blockedPage.on('pageerror', error => errors.push(error.message));
  await blockedPage.goto('http://localhost:5173');
  await blockedPage.getByText('Language applied for this session', {exact: true}).waitFor();
  await blockedPage.locator('.language-option').nth(1).click();
  await blockedPage.getByText('Язык изменён на время сеанса', {exact: true}).waitFor();
  await blocked.close();

  const invalid = await browser.newContext();
  await invalid.addInitScript(() => localStorage.setItem('interface-language', 'de'));
  const invalidPage = await invalid.newPage();
  await invalidPage.goto('http://localhost:5173');
  await invalidPage.getByRole('heading', {name: 'Make yourself at home.'}).waitFor();
  assert.equal(await invalidPage.evaluate(() => localStorage.getItem('interface-language')), 'en');
  assert.deepEqual(errors, []);
  await browser.close();
  console.log('PASS: EN/RU switching, Gravity UI translations, persistence, keyboard navigation, localized formats, mobile layout, blocked storage, invalid stored language, no browser errors.');
})().catch(error => {console.error(error); process.exit(1);});
EOF"

